--
-- Name: fetchareadetails(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.fetchareadetails(p_area_name text DEFAULT NULL::text, p_constituency_name text DEFAULT NULL::text, p_county_name text DEFAULT NULL::text, p_area_id integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(row_to_json(t))
        FROM (
            SELECT
                a.name::text AS area,
                c.name::text AS constituency,
                co.name::text AS county,
                r.name::text AS region,
                a.area_id,
                (a.geoLocation).lat,
                (a.geoLocation).long
            FROM
                PUBLIC.tbl_area a
                JOIN PUBLIC.tbl_constituency c ON a.cst_id = c.cst_id
                JOIN PUBLIC.tbl_county co ON c.cty_id = co.cty_id
                JOIN PUBLIC.tbl_region r ON co.reg_id = r.reg_id
            WHERE
                (p_area_name IS NULL OR LOWER(a.name) = LOWER(p_area_name))
                AND (p_area_id IS NULL OR a.area_id = p_area_id)
                AND (p_constituency_name IS NULL OR LOWER(c.name) = LOWER(p_constituency_name))
                AND (p_county_name IS NULL OR LOWER(co.name) = LOWER(p_county_name))
        ) t
    );
END $$;


ALTER FUNCTION kplcapp.fetchareadetails(p_area_name text, p_constituency_name text, p_county_name text, p_area_id integer) OWNER TO rora;

