--
-- Name: fetchoutages(integer, text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.fetchoutages(p_area_id integer, p_outage_type text, p_start_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP, p_end_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN COALESCE(
        (
            SELECT json_agg(row_to_json(t))
            FROM (
                SELECT
                    tto.ots_id,
                    tto.outage_date,
                    tto.outage_type,
                    tta.area_id,
                    tta.message::text AS details,
                    tta.oct_id,
                    ta.name::text AS area,
                    c.name::text AS constituency,
                    co.name::text AS county,
                    r.name::text AS region,
                    json_build_object(
                        'area', CASE
                            WHEN ta.geoLocation IS NOT NULL THEN
                                json_build_object(
                                    'lat', (ta.geoLocation).lat,
                                    'lng', (ta.geoLocation).long
                                )
                            ELSE
                                json_build_object(
                                    'lat', (co.geoLocation).lat,
                                    'lng', (co.geoLocation).long
                                )
                        END,
                        'region', json_build_object(
                            'lat', (r.geoLocation).lat,
                            'lng', (r.geoLocation).long
                        ),
                        'county', json_build_object(
                            'lat', (co.geoLocation).lat,
                            'lng', (co.geoLocation).long
                        )
                    ) AS coordinates
                FROM PUBLIC.tbl_outage tto
                JOIN PUBLIC.tbl_outage_area tta ON tto.ots_id = tta.ots_id
                JOIN PUBLIC.tbl_area ta ON tta.area_id = ta.area_id
                JOIN PUBLIC.tbl_constituency c ON ta.cst_id = c.cst_id
                JOIN PUBLIC.tbl_county co ON ta.cty_id = co.cty_id
                JOIN PUBLIC.tbl_region r ON co.reg_id = r.reg_id
                WHERE (p_area_id IS NULL OR tta.area_id = p_area_id)
                AND (p_outage_type IS NULL OR tto.outage_type = p_outage_type)
                AND tto.outage_date >= p_start_date
                AND tto.outage_date <= p_end_date
            ) t
        ),
        '[]'::json
    );
END $$;


ALTER FUNCTION kplcapp.fetchoutages(p_area_id integer, p_outage_type text, p_start_date timestamp without time zone, p_end_date timestamp without time zone) OWNER TO rora;

--
-- Name: fetchoutages(integer, integer, integer, text, timestamp without time zone, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.fetchoutages(p_area_id integer, p_county_id integer, p_region_id integer, p_outage_type text, p_start_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP, p_end_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN COALESCE((
        WITH filtered_outages AS (
            -- First CTE: Get all outages matching our basic criteria
            SELECT
                tto.ots_id,
                tto.outage_date,
                tto.outage_type,
                tta.area_id,
                tta.message,
                tta.oct_id
            FROM PUBLIC.tbl_outage tto
            JOIN PUBLIC.tbl_outage_area tta ON tto.ots_id = tta.ots_id
            WHERE tto.outage_date BETWEEN p_start_date AND p_end_date
            AND (p_outage_type IS NULL OR tto.outage_type LIKE '%' || p_outage_type || '%')
        ),
        area_details AS (
            -- Second CTE: Get area and location information
            SELECT
                ta.area_id,
                ta.name AS area_name,
                c.name AS constituency_name,
                co.name AS county_name,
                r.name AS region_name,
                ta.geoLocation AS area_location,
                co.geoLocation AS county_location,
                r.geoLocation AS region_location
            FROM PUBLIC.tbl_area ta
            JOIN PUBLIC.tbl_constituency c ON ta.cst_id = c.cst_id
            JOIN PUBLIC.tbl_county co ON ta.cty_id = co.cty_id
            JOIN PUBLIC.tbl_region r ON co.reg_id = r.reg_id
            WHERE (p_area_id IS NULL OR ta.area_id = p_area_id)
            AND (p_county_id IS NULL OR ta.cty_id = p_county_id)
            AND (p_region_id IS NULL OR r.reg_id = p_region_id)
        ),
        outage_counts AS (
            -- Third CTE: Calculate outage counts per area and outage type
            SELECT
                area_id,
                outage_type,
                COUNT(*) as count
            FROM filtered_outages
            GROUP BY area_id, outage_type
        ),
        latest_outages AS (
            -- Fourth CTE: Get only the latest outage per area
            SELECT DISTINCT ON (fo.area_id)
                fo.ots_id,
                fo.outage_date,
                fo.outage_type,
                fo.area_id,
                fo.message,
                fo.oct_id,
                oc.count as outage_count,  -- This will now be count for specific outage type
                ad.area_name,
                ad.constituency_name,
                ad.county_name,
                ad.region_name,
                ad.area_location,
                ad.county_location,
                ad.region_location
            FROM filtered_outages fo
            JOIN area_details ad ON fo.area_id = ad.area_id
            JOIN outage_counts oc ON fo.area_id = oc.area_id
                AND fo.outage_type = oc.outage_type  -- Added join condition for outage_type
            ORDER BY fo.area_id, fo.outage_date DESC
        )
        SELECT json_agg(row_to_json(t))
        FROM (
            SELECT
                ots_id,
                outage_date,
                outage_type,
                area_id,
                message::text AS details,
                oct_id,
                area_name AS area,
                constituency_name AS constituency,
                county_name AS county,
                region_name AS region,
                outage_count,
                json_build_object(
                    'area', CASE
                        WHEN area_location IS NOT NULL THEN
                            json_build_object(
                                'lat', (area_location).lat,
                                'lng', (area_location).long
                            )
                        ELSE
                            json_build_object(
                                'lat', (county_location).lat,
                                'lng', (county_location).long
                            )
                    END,
                    'region', json_build_object(
                        'lat', (region_location).lat,
                        'lng', (region_location).long
                    ),
                    'county', json_build_object(
                        'lat', (county_location).lat,
                        'lng', (county_location).long
                    )
                ) AS coordinates
            FROM latest_outages
        ) t
    ), '[]'::json);
END $$;


ALTER FUNCTION kplcapp.fetchoutages(p_area_id integer, p_county_id integer, p_region_id integer, p_outage_type text, p_start_date timestamp without time zone, p_end_date timestamp without time zone) OWNER TO rora;

