--
-- Name: fuzzysearchareadetails(text, text, text, double precision); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.fuzzysearchareadetails(p_region_name text, p_county_name text DEFAULT NULL::text, p_area_name text DEFAULT NULL::text, p_similarity_threshold double precision DEFAULT 0.7) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(row_to_json(t))
        FROM (
            SELECT
                a.area_id,
                a.name::text AS area,
                c.cst_id,
                c.name::text AS constituency,
                co.cty_id,
                co.name::text AS county,
                co.code::text AS county_code,
                r.reg_id,
                r.name::text AS region,
                (a.geoLocation).lat,
                (a.geoLocation).long,
                CASE
                    WHEN p_area_name IS NOT NULL THEN 1 - (levenshtein(LOWER(a.name), LOWER(p_area_name))::float / GREATEST(length(a.name), length(p_area_name)))
                    WHEN p_county_name IS NOT NULL THEN 1 - (levenshtein(LOWER(co.name), LOWER(p_county_name))::float / GREATEST(length(co.name), length(p_county_name)))
                    ELSE 1
                END AS match_similarity
            FROM
                PUBLIC.tbl_region r
                LEFT JOIN PUBLIC.tbl_county co ON r.reg_id = co.reg_id
                LEFT JOIN PUBLIC.tbl_constituency c ON co.cty_id = c.cty_id
                LEFT JOIN PUBLIC.tbl_area a ON c.cst_id = a.cst_id
            WHERE
                LOWER(r.name) ILIKE '%' || LOWER(p_region_name) || '%'
                AND (
                    p_county_name IS NULL
                    OR LOWER(co.name) ILIKE '%' || LOWER(p_county_name) || '%'
                )
                AND (
                    p_area_name IS NULL
                    OR LOWER(a.name) ILIKE '%' || LOWER(p_area_name) || '%'
                )
            ORDER BY
                (1 - (levenshtein(LOWER(r.name), LOWER(p_region_name))::float / GREATEST(length(r.name), length(p_region_name)))) DESC,
                CASE
                    WHEN p_county_name IS NOT NULL THEN 1 - (levenshtein(LOWER(co.name), LOWER(p_county_name))::float / GREATEST(length(co.name), length(p_county_name)))
                    ELSE 1
                END DESC,
                CASE
                    WHEN p_area_name IS NOT NULL THEN 1 - (levenshtein(LOWER(a.name), LOWER(p_area_name))::float / GREATEST(length(a.name), length(p_area_name)))
                    ELSE 1
                END DESC
        ) t
    );
END $$;


ALTER FUNCTION kplcapp.fuzzysearchareadetails(p_region_name text, p_county_name text, p_area_name text, p_similarity_threshold double precision) OWNER TO rora;

--
-- Name: getuserdata(integer, text, text); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.getuserdata(p_user_id integer DEFAULT NULL::integer, p_email text DEFAULT NULL::text, p_msisdn text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_data json;
BEGIN
    SELECT json_build_object(
        'cnt_id', c.cnt_id,
        'area_id', c.area_id,
        'msisdn', c.msisdn,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', u.email,
        'blocked', u.blocked,
        'otp_verified', u.otp_verified,
        'date_created', u.date_created,
        'last_update', u.last_update,
        'subscription', CASE
            WHEN s.name IS NOT NULL THEN
                json_build_object(
                    'sub_id', s.sub_id,
                    'name', s.name,
                    'description', s.description,
                    'price', s.amount
                )
            ELSE NULL
        END
    ) INTO user_data
    FROM PUBLIC.tbl_contact c
    JOIN PUBLIC.tbl_user_hash u ON c.cnt_id = u.cnt_id
    LEFT JOIN PUBLIC.tbl_subscription s ON c.sub_id = s.sub_id
    WHERE (p_user_id IS NULL OR c.cnt_id = p_user_id)
    AND (p_email IS NULL OR u.email = p_email)
    AND (p_msisdn IS NULL OR c.msisdn = p_msisdn);

    IF user_data IS NULL THEN
        RAISE EXCEPTION 'User  % not found', p_email;
    END IF;

    RETURN user_data;
END $$;


ALTER FUNCTION kplcapp.getuserdata(p_user_id integer, p_email text, p_msisdn text) OWNER TO rora;

--
-- Name: insertareadata(jsonb); Type: PROCEDURE; Schema: public; Owner: rora
--

CREATE PROCEDURE kplcapp.insertareadata(IN areadata jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    region_record jsonb;
    county_record jsonb;
    constituency_record jsonb;
    area_record jsonb;
    region_name text;
    county_name text;
    county_code text;
    constituency_name text;
    area_name text;
    region_lat float;
    region_long float;
    county_lat float;
    county_long float;
    area_lat float;
    area_long float;
    region_id int;
    county_id int;
    constituency_id int;
BEGIN
    RAISE NOTICE 'Starting InsertAreaData procedure';
    RAISE NOTICE 'AreaData type: %', jsonb_typeof(AreaData);

    -- Iterate over each region in the JSON array
    FOR region_record IN SELECT * FROM jsonb_array_elements(AreaData)
    LOOP
        RAISE NOTICE 'Processing region: %', region_record->>'region';
        -- Extract region data
        region_name := region_record->>'region';
        region_lat := NULLIF(TRIM(region_record->'geoLocation'->>'latitude'), '')::float;
        region_long := NULLIF(TRIM(region_record->'geoLocation'->>'longitude'), '')::float;

        -- Insert or update Region
        SELECT reg_id INTO region_id FROM kplcapp.tbl_region WHERE name = region_name;
        IF region_id IS NULL THEN
            VALUES (region_name, ROW(region_lat, region_long)::kplcapp.geo)
            RETURNING reg_id INTO region_id;
        ELSE
            UPDATE kplcapp.tbl_region
            SET geoLocation = ROW(region_lat, region_long)::kplcapp.geo
            WHERE reg_id = region_id;
        END IF;

        RAISE NOTICE 'Counties type: %', jsonb_typeof(region_record->'counties');
        -- Iterate over counties in the region
        FOR county_record IN SELECT * FROM jsonb_array_elements(region_record->'counties')
        LOOP
            RAISE NOTICE 'Processing county: %', county_record->>'name';
            -- Extract county data
            county_name := county_record->>'name';
            county_code := county_record->>'code';
            county_lat := NULLIF(TRIM(county_record->'geoLocation'->>'latitude'), '')::float;
            county_long := NULLIF(TRIM(county_record->'geoLocation'->>'longitude'), '')::float;

            -- Insert or update County
            SELECT cty_id INTO county_id FROM kplcapp.tbl_county WHERE name = county_name;
            IF county_id IS NULL THEN
                VALUES (region_id, county_name, county_code, ROW(county_lat, county_long)::kplcapp.geo)
                RETURNING cty_id INTO county_id;
            ELSE
                UPDATE kplcapp.tbl_county
                SET reg_id = region_id,
                    code = county_code,
                    geoLocation = ROW(county_lat, county_long)::kplcapp.geo
                WHERE cty_id = county_id;
            END IF;

            RAISE NOTICE 'Constituencies type: %', jsonb_typeof(county_record->'constituencies');
            -- Iterate over constituencies in the county
            FOR constituency_record IN SELECT * FROM jsonb_array_elements(county_record->'constituencies')
            LOOP
                RAISE NOTICE 'Processing constituency: %', constituency_record->>'name';
                -- Extract constituency data
                constituency_name := constituency_record->>'name';

                -- Insert or update Constituency
                SELECT cst_id INTO constituency_id FROM kplcapp.tbl_constituency WHERE name = constituency_name;
                IF constituency_id IS NULL THEN
                    VALUES (county_id, constituency_name)
                    RETURNING cst_id INTO constituency_id;
                ELSE
                    UPDATE kplcapp.tbl_constituency
                    SET cty_id = county_id
                    WHERE cst_id = constituency_id;
                END IF;

                RAISE NOTICE 'Areas type: %', jsonb_typeof(constituency_record->'areas');
                -- Iterate over areas in the constituency
                FOR area_record IN SELECT * FROM jsonb_array_elements(constituency_record->'areas')
                LOOP
                    RAISE NOTICE 'Processing area: %', area_record->>'name';
                    -- Extract area data
                    area_name := area_record->>'name';
                    area_lat := NULLIF(TRIM(area_record->'geoLocation'->>'latitude'), '')::float;
                    area_long := NULLIF(TRIM(area_record->'geoLocation'->>'longitude'), '')::float;

                    -- Insert or update Area
                    IF EXISTS (SELECT 1 FROM kplcapp.tbl_area WHERE name = area_name) THEN
                        UPDATE kplcapp.tbl_area
                        SET cst_id = constituency_id,
                            cty_id = county_id,
                            geoLocation =
                                CASE
                                    WHEN area_lat IS NOT NULL AND area_long IS NOT NULL THEN
                                        ROW(area_lat, area_long)::kplcapp.geo
                                    ELSE
                                        kplcapp.tbl_area.geoLocation
                                END
                        WHERE name = area_name;
                    ELSE
                        VALUES (
                            constituency_id,
                            county_id,
                            area_name,
                            CASE
                                WHEN area_lat IS NOT NULL AND area_long IS NOT NULL THEN
                                    ROW(area_lat, area_long)::kplcapp.geo
                                ELSE
                                    NULL
                            END
                        );
                    END IF;
                END LOOP;
            END LOOP;
        END LOOP;
    END LOOP;

    RAISE NOTICE 'InsertAreaData procedure completed successfully';
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error occurred: % %', SQLERRM, SQLSTATE;
END;
$$;


ALTER PROCEDURE kplcapp.insertareadata(IN areadata jsonb) OWNER TO rora;

--
-- Name: insertareageodata(jsonb); Type: PROCEDURE; Schema: public; Owner: rora
--

CREATE PROCEDURE kplcapp.insertareageodata(IN areageodata jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    record jsonb;
    area_name text;
    latitude float;
    longitude float;
    area_id integer;
BEGIN
    -- Iterate over each item in the JSON array
    FOR record IN SELECT * FROM jsonb_array_elements(AreaGeoData)
    LOOP
      RAISE NOTICE 'Processing record: %', record;
        -- Extract fields from the current JSON object
        area_name := record->>'area';
        latitude := record->>'latitude'::float;
        longitude := record->>'longitude'::float;

        -- Find the area_id based on area name
        SELECT area_id INTO area_id FROM kplcapp.tbl_area WHERE name = area_name;
        -- Update the geoLocation in tbl_area
        UPDATE kplcapp.tbl_area
        SET geoLocation = ROW(latitude, longitude)::kplcapp.geo
        WHERE area_id = area_id;
    END LOOP;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error occurred: %', SQLERRM;
END;
$$;


ALTER PROCEDURE kplcapp.insertareageodata(IN areageodata jsonb) OWNER TO rora;

