--
-- Name: insertuser(jsonb); Type: PROCEDURE; Schema: public; Owner: rora
--

CREATE PROCEDURE kplcapp.insertuser(IN contactdata jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    record jsonb;
    p_area_id integer;
    p_first_name text;
    p_last_name text;
    p_email text;
    p_password text;
    p_msisdn text;
    p_cnt_id integer;
    p_sub_id integer;
    p_subscription_type text;
BEGIN
    -- Iterate over each item in the JSON array
    FOR record IN SELECT * FROM jsonb_array_elements(ContactData)
    LOOP
        -- Extract fields from the current JSON object
        p_area_id := (record->>'area_id')::integer;
        p_msisdn := record->>'msisdn';
        p_first_name := record->>'first_name';
        p_last_name := record->>'last_name';
        p_email := record->>'email';
        p_password := record->>'password_hash';
        p_subscription_type := record->>'subscription_type';

        -- Check if a contact with the same MSISDN already exists
        IF EXISTS (SELECT 1 FROM kplcapp.tbl_contact WHERE msisdn = p_msisdn) THEN
            RAISE EXCEPTION 'Contact with MSISDN % already exists', p_msisdn;
        END IF;

        -- Check if a user with the same email already exists
        IF EXISTS (SELECT 1 FROM kplcapp.tbl_user_hash WHERE email = p_email) THEN
            RAISE EXCEPTION 'User with email % already exists', p_email;
        END IF;

        -- If we reach here, both MSISDN and email are unique, so we can insert
        -- Insert Contact
         -- Get the subscription id
        SELECT sub_id INTO p_sub_id FROM kplcapp.tbl_subscription
        WHERE name = p_subscription_type
        LIMIT 1;

        VALUES (p_area_id, p_msisdn, p_first_name, p_last_name, p_sub_id)
        RETURNING cnt_id INTO p_cnt_id;

        -- Insert UserHash
        VALUES (p_cnt_id, p_email, p_password);

      -- Call GetUserData to get the inserted user's data
        -- SELECT * FROM PUBLIC.GetUserData(p_cnt_id) INTO result;
    END LOOP;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error occurred: %', SQLERRM;
END $$;


ALTER PROCEDURE kplcapp.insertuser(IN contactdata jsonb) OWNER TO rora;

