--
-- Name: savetoken(text, integer, character varying, timestamp without time zone, boolean); Type: PROCEDURE; Schema: public; Owner: rora
--

CREATE PROCEDURE kplcapp.savetoken(IN p_token text, IN p_user_id integer, IN p_type character varying, IN p_expires_at timestamp without time zone, IN p_blacklisted boolean DEFAULT false)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Try to update existing token
    UPDATE PUBLIC.tbl_auth_tokens
    SET
        expires_at = p_expires_at,
        blacklisted = p_blacklisted,
        created_at = CURRENT_TIMESTAMP
    WHERE token = p_token
    AND cnt_id = p_user_id;

    -- If no row was updated, insert new token
    IF NOT FOUND THEN
            token,
            cnt_id,
            type,
            expires_at,
            blacklisted,
            created_at
        )
        VALUES (
            p_token,
            p_user_id,
            p_type,
            p_expires_at,
            p_blacklisted,
            CURRENT_TIMESTAMP
        );
    END IF;

    COMMIT;
END $$;


ALTER PROCEDURE kplcapp.savetoken(IN p_token text, IN p_user_id integer, IN p_type character varying, IN p_expires_at timestamp without time zone, IN p_blacklisted boolean) OWNER TO rora;

--
-- Name: tokensdelete(text, integer); Type: PROCEDURE; Schema: public; Owner: rora
--

CREATE PROCEDURE kplcapp.tokensdelete(IN p_token text DEFAULT NULL::text, IN p_user_id integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM PUBLIC.tbl_auth_tokens
    WHERE (p_token IS NULL OR token = p_token)
    AND (p_user_id IS NULL OR cnt_id = p_user_id);

    COMMIT;
END $$;


ALTER PROCEDURE kplcapp.tokensdelete(IN p_token text, IN p_user_id integer) OWNER TO rora;

--
-- Name: tokensget(text, integer); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.tokensget(p_token text DEFAULT NULL::text, p_user_id integer DEFAULT NULL::integer) RETURNS TABLE(token_id integer, cnt_id integer, token text, created_at timestamp without time zone, expires_at timestamp without time zone, blacklisted boolean, type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT t.token_id, t.cnt_id, t.token, t.created_at, t.expires_at, t.blacklisted, t.type
    FROM PUBLIC.tbl_auth_tokens t
    WHERE (p_token IS NULL OR t.token = p_token) OR
    (p_user_id IS NULL OR t.cnt_id = p_user_id)
    ORDER BY t.created_at DESC LIMIT 1;
END $$;


ALTER FUNCTION kplcapp.tokensget(p_token text, p_user_id integer) OWNER TO rora;

