--
-- Name: useridentitycheck(text); Type: FUNCTION; Schema: public; Owner: rora
--

CREATE FUNCTION kplcapp.useridentitycheck(p_identifier text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_data json;
BEGIN
    SELECT json_build_object(
        'cnt_id', c.cnt_id,
        'area_id', c.area_id,
        'msisdn', c.msisdn,
        'first_name', c.first_name,
        'last_name', c.last_name,
        'email', u.email,
        'password_hash', u.password_hash,
        'blocked', u.blocked,
        'blocked_reason', u.blocked_reason,
        'otp_verified', u.otp_verified,
        'date_created', u.date_created,
        'last_update', u.last_update,
        'subscription', CASE
            WHEN s.name IS NOT NULL THEN
                json_build_object(
                    'name', s.name,
                    'description', s.description,
                    'price', s.amount
                )
            ELSE NULL
        END
    )
    INTO user_data
    FROM kplcapp.tbl_contact c
    JOIN kplcapp.tbl_user_hash u ON c.cnt_id = u.cnt_id
    LEFT JOIN kplcapp.tbl_subscription s ON c.sub_id = s.sub_id
    WHERE u.email = p_identifier OR c.msisdn = p_identifier;

    -- Check if user exists
    IF user_data IS NULL THEN
        RAISE EXCEPTION 'Invalid Details: User not found';
    END IF;

    -- Check if user is blocked
    IF (user_data->>'blocked')::boolean THEN
        RAISE EXCEPTION 'User is blocked. Reason: %', user_data->>'blocked_reason';
    END IF;

    -- Check if OTP is verified
    IF NOT (user_data->>'otp_verified')::boolean THEN
        RAISE EXCEPTION 'OTP not verified';
    END IF;

    RETURN user_data;
END;
$$;


ALTER FUNCTION kplcapp.useridentitycheck(p_identifier text) OWNER TO rora;

